#!/usr/bin/env bash
set -Eeuo pipefail
TMP="$(mktemp -d)"
trap 'rm -rf "$TMP"' EXIT
cat <<'B64' | base64 -d > "$TMP/hyper-cs16-fastdl-v8.py"

B64
cat <<'B64' | base64 -d > "$TMP/hyper-cs16-ctl-wrapper-v8.py"

B64
cat <<'B64' | base64 -d > "$TMP/patch-core-v8.py"

B64
cat <<'B64' | base64 -d > "$TMP/core-fastdl-override-v8.py.txt"

B64
cat <<'B64' | base64 -d > "$TMP/apply-cs16-fastdl-final-v8.sh"

B64
chmod +x "$TMP/"*.sh "$TMP/"*.py 2>/dev/null || true
exec bash "$TMP/apply-cs16-fastdl-final-v8.sh" "${1:-/root/hyper-hosting-panel}" "${2:-25}"
